COMMIT;

SELECT
    e.id_evento,
    u.codigo_slug,
    u.nome AS nome_upa,
    u.bairro,
    e.etapa,
    e.tipo_evento,
    e.prioridade,
    e.classificacao_risco,
    e.ref_senha,
    e.data_hora_ocorrido
FROM T_UPA_EVENTO_SENHA e
INNER JOIN T_UPA_UNIDADE u ON e.id_unidade = u.id_unidade
ORDER BY e.data_hora_ocorrido DESC;

SELECT
    u.id_unidade,
    u.nome AS nome_unidade,
    e.tipo_evento,
    e.etapa,
    COUNT(e.id_evento) AS total_eventos
FROM T_UPA_UNIDADE u
INNER JOIN T_UPA_EVENTO_SENHA e ON u.id_unidade = e.id_unidade
GROUP BY u.id_unidade, u.nome, e.tipo_evento, e.etapa
ORDER BY u.id_unidade, total_eventos DESC;

SELECT
    u.id_unidade,
    u.codigo_slug,
    u.nome AS nome_unidade,
    u.tipo,
    u.bairro,
    u.cidade,
    u.distancia_km,
    u.tempo_deslocamento_min,
    u.status_integracao,
    COUNT(e.id_evento) AS total_senhas_processadas
FROM T_UPA_UNIDADE u
LEFT OUTER JOIN T_UPA_EVENTO_SENHA e ON u.id_unidade = e.id_unidade
WHERE u.status_integracao IN ('ONLINE', 'STALE', 'SEM_DADOS')
GROUP BY u.id_unidade, u.codigo_slug, u.nome, u.tipo, u.bairro, u.cidade, u.distancia_km, u.tempo_deslocamento_min, u.status_integracao
ORDER BY u.distancia_km ASC;